                ST420_GRP_CLOSE := FALSE;
                steg := 6;
            END_IF;
        6:
            (* Roboten gar tillbaka till hemlaget. *)
            IF tmrRor.Q THEN
                steg := 7;
            END_IF;
        7:
            (* Cykeln ar klar och robotprogrammet stoppas forst har. *)
            ST420_RB_START := FALSE;
            IF NOT ST420_PRT_PRS THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
ELSE
    (* Sakert lage = ingen kraft pa nagot don. *)
    ST420_GRP_CLOSE := FALSE;
END_IF;

(* Roboten halls stilla med matningen kvar och lagesbilden behallen: ett
   kategori 2-stopp enligt IEC 60204-1:2016 9.2.2. Robotprogrammet stoppas
   inte, det halls. *)
ST420_RB_HOLD := NOT xDriftsklar;

(* Stoppgrinden stangs vid stopp och haller dessutom tillbaka nasta detalj
   sa lange cellen arbetar med en. *)
ST420_STP_CLOSE := (NOT xDriftsklar) OR (steg > 0);

ST420_STA_SAFE := tmrSafe.Q;
ST420_STA_STEP := steg;
END_PROGRAM

PROGRAM ST420_CELLSTOPP
VAR
    steg         : INT := 0;
    trigReset    : R_TRIG;
    tmrSafe      : TON;
    tmrRor       : TON;
    xStopp       : BOOL := FALSE;
    xLarm        : BOOL := FALSE;
    xKravOmstart : BOOL := TRUE;
    xDriftsklar  : BOOL := FALSE;
    xRor         : BOOL := FALSE;
END_VAR

(* EMG_OK och ST420_LGT_CLEAR ligger pa sakerhets-PLC och lases bara har.
   Den har logiken ror inte sjalva sakerhetsfunktionen; den ar forreglad AV
   den. *)
trigReset(CLK := SYS_RESET);

(* Kvittensen ar en HANDLING och lases som en stigande flank. Nivan racker
   inte: en kvitteringsknapp som star kvar hog skulle starta cellen i samma
   stund som nodstoppsdonet dras upp, och just det forbjuder ISO 13850:2015
   4.1.4 och IEC 60204-1:2016 9.2.3.4.2. Aterstart kraver dessutom en
   obruten ljusrida. *)
IF trigReset.Q AND EMG_OK AND ST420_LGT_CLEAR THEN
    xStopp := FALSE;
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF;

(* Stopptillstandet latchas. Cellen vaknar dessutom med xKravOmstart hog, sa
   den startar inte heller nar spanningen kommer tillbaka
   (IEC 60204-1:2016 7.5). *)
IF NOT EMG_OK OR NOT ST420_LGT_CLEAR THEN
    xStopp := TRUE;
    xKravOmstart := TRUE;
END_IF;

(* Greppet halls av tryckluft och kraften kan sjunka under ett langt stopp.
   En konsol pa 2,6 kg kraver minst 120 N och deformeras over 500 N.
   Kraften provas forst nar greppet ar uppbyggt, alltsa fran steg 4. *)
IF ST420_GRP_CLOSE AND steg >= 4
        AND (ST420_GRP_FORCE < 120.0 OR ST420_GRP_FORCE > 500.0) THEN
    xLarm := TRUE;
END_IF;

(* Ett steg utanfor sekvensen 0 till 7 gar inte att fortsatta fran. *)
IF steg < 0 OR steg > 7 THEN
    xLarm := TRUE;
    xStopp := TRUE;
END_IF;

SYS_ALARM := xLarm;

xDriftsklar := EMG_OK AND ST420_LGT_CLEAR AND NOT xStopp
        AND NOT xKravOmstart AND NOT xLarm;

(* Sakert lage ar en BEKRAFTELSE och inte ett kommando. Kedjan ar PLC:ns
   svarstid 40 ms, utgangsrelat 25 ms och stoppgrindens slag 120 ms, alltsa
   185 ms. Forst da star cellen verkligen still med grinden slagen. Kravet
   0,30 s lamnar 115 ms marginal. *)
tmrSafe(IN := NOT xDriftsklar, PT := T#185ms);

(* Sekvensen stegas BARA nar cellen ar driftsklar. Den nollstalls aldrig av
   ett stopp: steget ar cellens lagesbild, och en cell som borjar om fran
   noll med en detalj i griparen ar farligare an en som star still. *)
xRor := xDriftsklar AND (steg = 1 OR steg = 4 OR steg = 6);
tmrRor(IN := xRor, PT := T#400ms);

IF xDriftsklar THEN
    CASE steg OF
        0:
            (* Tomgang: fixturen ar tom och roboten far hamta en konsol. *)
            ST420_GRP_CLOSE := FALSE;
            IF NOT ST420_PRT_PRS THEN
                ST420_RB_START := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Roboten gar till hamtlaget bakom stoppgrinden. *)
            IF tmrRor.Q THEN
                steg := 2;
            END_IF;
        2:
            (* Griparen sluts om konsolen. *)
            ST420_GRP_CLOSE := TRUE;
            steg := 3;
        3:
            (* Greppet ska byggas upp till minst 120 N fore lyftet. *)
            IF ST420_GRP_FORCE >= 120.0 THEN
                steg := 4;
            END_IF;
        4:
            (* Roboten bar konsolen till fixturen. *)
            IF tmrRor.Q THEN
                steg := 5;
            END_IF;
        5:
            (* Konsolen sitter i fixturen och greppet far slappa. *)
            IF ST420_PRT_PRS THEN
                ST420_GRP_CLOSE := FALSE;
                steg := 6;
            END_IF;
        6:
            (* Roboten gar tillbaka till hemlaget. *)
            IF tmrRor.Q THEN
                steg := 7;
            END_IF;
        7:
            (* Cykeln ar klar och robotprogrammet stoppas forst har. *)
            ST420_RB_START := FALSE;
            IF NOT ST420_PRT_PRS THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Roboten halls stilla med matningen kvar och lagesbilden behallen: ett
   kategori 2-stopp enligt IEC 60204-1:2016 9.2.2. Robotprogrammet stoppas
   inte, det halls. *)
ST420_RB_HOLD := NOT xDriftsklar;

(* Stoppgrinden stangs vid stopp och haller dessutom tillbaka nasta detalj
   sa lange cellen arbetar med en. *)
ST420_STP_CLOSE := (NOT xDriftsklar) OR (steg > 0);

ST420_STA_SAFE := NOT xDriftsklar;
ST420_STA_STEP := steg;
END_PROGRAM
